class Solution:
    def checkValidString(self, s):
        st = []   # stack for '(' indices
        sr = []   # stack for '*' indices
        for i, ch in enumerate(s):
            if ch == '(':
                st.append(i)
            elif ch == '*':
                sr.append(i)
            else:  # ')'
                if st:
                    st.pop()
                elif sr:
                    sr.pop()
                else:
                    return False
        while st:
            if not sr:
                return False
            if st[-1] < sr[-1]:
                st.pop()
                sr.pop()
            else:
                return False
        return True

