from typing import List

class Solution:
    def palindromePairs(self, words: List[str]) -> List[List[int]]:
        if not words:
            return []
        backward = {}
        for i, word in enumerate(words):
            backward[word[::-1]] = i

        res = []
        for i, word in enumerate(words):
            # word reversed exists (excluding itself)
            if word in backward and backward[word] != i:
                res.append([i, backward[word]])

            # handle empty string cases
            if word != "" and "" in backward and word == word[::-1]:
                j = backward[""]
                if i != j:
                    res.append([i, j])
                    res.append([j, i])

            # split word into prefix and suffix
            for j in range(len(word)):
                prefix = word[:j]
                suffix = word[j:]

                # prefix palindrome -> need reversed suffix
                if prefix == prefix[::-1] and suffix[::-1] in backward:
                    k = backward[suffix[::-1]]
                    if k != i:
                        res.append([k, i])

                # suffix palindrome -> need reversed prefix
                if suffix == suffix[::-1] and prefix[::-1] in backward:
                    k = backward[prefix[::-1]]
                    if k != i:
                        res.append([i, k])

        # optional: remove duplicate pairs
        uniq = set(tuple(p) for p in res)
        return [list(p) for p in uniq]

