from functools import lru_cache

class Solution:
    def numberOfArrays(self, s: str, k: int) -> int:
        n = len(s)
        MOD = 10**9 + 7

        @lru_cache(None)
        def dfs(i: int) -> int:
            if i == n:
                return 1
            if s[i] == '0':
                return 0
            res = 0
            cur = 0
            for j in range(i, n):
                cur = cur * 10 + (ord(s[j]) - ord('0'))
                if cur > k:
                    break
                res += dfs(j + 1)
                if res >= MOD:
                    res -= MOD
            return res % MOD

        return dfs(0)

